files.content:
:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a3c;
  --text: #f0f0f5;
  --accent: #6c63ff;
  --accent-hover: #5a52d5;
  --accent-active: #4a42b0;
  --border: #3d3d55;
  --focus: #ffcc00;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1rem;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 2rem;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

h1 {
  font-size: 1.5rem;
  font-weight: 600;
  text-align: center;
  letter-spacing: 0.5px;
}

.preview {
  width: 100%;
  height: 160px;
  border-radius: 12px;
  background: #000;
  border: 2px solid var(--border);
  transition: background 0.15s ease;
}

.hex {
  font-size: 1.75rem;
  font-weight: 700;
  text-align: center;
  font-family: 'SF Mono', 'Fira Code', monospace;
  letter-spacing: 2px;
  color: var(--text);
}

.sliders {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.slider-group {
  display: grid;
  grid-template-columns: 4rem 1fr 3rem;
  align-items: center;
  gap: 0.75rem;
}

.slider-group label {
  font-weight: 500;
  font-size: 1rem;
}

.slider-group output {
  font-family: 'SF Mono', 'Fira Code', monospace;
  font-size: 1rem;
  text-align: right;
  color: var(--text);
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 8px;
  border-radius: 4px;
  background: var(--border);
  outline: none;
  cursor: pointer;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  border: 2px solid var(--text);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
}

input[type="range"]::-moz-range-thumb {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  border: 2px solid var(--text);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
}

input[type="range"]:hover::-webkit-slider-thumb {
  background: var(--accent-hover);
}

input[type="range"]:hover::-moz-range-thumb {
  background: var(--accent-hover);
}

input[type="range"]:active::-webkit-slider-thumb {
  background: var(--accent-active);
  transform: scale(1.1);
}

input[type="range"]:active::-moz-range-thumb {
  background: var(--accent-active);
  transform: scale(1.1);
}

input[type="range"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 4px;
}

button {
  padding: 0.875rem 1.5rem;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
}

button:hover {
  background: var(--accent-hover);
}

button:active {
  background: var(--accent-active);
  transform: scale(0.98);
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

@media (max-width: 400px) {
  .card {
    padding: 1.25rem;
    gap: 1rem;
  }
  .preview {
    height: 120px;
  }
  .hex {
    font-size: 1.5rem;
  }
  .slider-group {
    grid-template-columns: 3.5rem 1fr 2.5rem;
    gap: 0.5rem;
  }
}

(function () {
  'use strict';

  var sliders = {
    red: document.getElementById('red'),
    green: document.getElementById('green'),
    blue: document.getElementById('blue')
  };
  var outputs = {
    red: document.getElementById('red-value'),
    green: document.getElementById('green-value'),
    blue: document.getElementById('blue-value')
  };
  var preview = document.getElementById('preview');
  var hexDisplay = document.getElementById('hex');
  var randomBtn = document.getElementById('random');

  function toHex(value) {
    var hex = value.toString(16).toUpperCase();
    return hex.length === 1 ? '0' + hex : hex;
  }

  function updateColor() {
    var r = parseInt(sliders.red.value, 10);
    var g = parseInt(sliders.green.value, 10);
    var b = parseInt(sliders.blue.value, 10);

    // Update visual outputs and ARIA values
    outputs.red.textContent = r;
    outputs.green.textContent = g;
    outputs.blue.textContent = b;
    sliders.red.setAttribute('aria-valuenow', r);
    sliders.green.setAttribute('aria-valuenow', g);
    sliders.blue.setAttribute('aria-valuenow', b);

    // Update preview and hex code
    preview.style.backgroundColor = 'rgb(' + r + ',' + g + ',' + b + ')';
    hexDisplay.textContent = '#' + toHex(r) + toHex(g) + toHex(b);
  }

  function randomize() {
    sliders.red.value = Math.floor(Math.random() * 256);
    sliders.green.value = Math.floor(Math.random() * 256);
    sliders.blue.value = Math.floor(Math.random() * 256);
    updateColor();
  }

  // Attach event listeners
  Object.keys(sliders).forEach(function (key) {
    sliders[key].addEventListener('input', updateColor);
  });
  randomBtn.addEventListener('click', randomize);

  // Initialize
  updateColor();
})();
